def f(N: int, M: int, edges: List[Tuple[int, int]]): 
    # Write your code here
    graph = [[] for _ in range(N+1)]
    in_degree = [0] * (N+1)
    out_degree = [0] * (N+1)
    for edge in edges:
        u, v = edge
        graph[u].append(v)
        out_degree[u] += 1
        in_degree[v] += 1

    paths = [[0] * (N+1) for _ in range(N+1)]
    paths[1][1] = 1
    for i in range(1, N+1):
        for u in range(1, N+1):
            if paths[u][i] > 0:
                for v in graph[u]:
                    if paths[v][i+1] == 0:
                        paths[v][i+1] = paths[u][i]
                    else:
                        paths[v][i+1] += paths[u][i]

    return [sum(paths[u][i] for u in range(1, N+1)) for i in range(1, N+1)]
```

